<?php declare(strict_types=1); function d(string $f):array{$p=__DIR__.'/data/'.$f;$x=is_file($p)?json_decode((string)file_get_contents($p),true):[];return is_array($x)?$x:[];}function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$doctor=d('doctor.json');$about=d('about.json');$expertise=d('expertise.json');$research=d('research.json');$contact=d('contact.json');?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($doctor['name']??'Doktor')?> — <?=e($doctor['title']??'Portfolio')?></title><style>:root{--b:#f7f9fb;--t:#10202b;--m:#66757e;--l:#dfe7eb;--a:#155eef}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--b);color:var(--t);font:16px/1.6 Inter,system-ui,sans-serif}a{text-decoration:none;color:inherit}.nav,.wrap{max-width:1180px;margin:auto;padding-left:24px;padding-right:24px}.nav{position:sticky;top:14px;z-index:5;padding-top:12px;padding-bottom:12px;background:#ffffffd9;backdrop-filter:blur(20px);border:1px solid #fff;border-radius:20px;display:flex;align-items:center;justify-content:space-between}.links{display:flex;gap:22px;font-size:13px;color:var(--m)}.cta,.btn{padding:11px 16px;border-radius:13px}.cta,.primary{background:var(--t);color:#fff}.hero{min-height:80vh;display:grid;grid-template-columns:1.1fr .9fr;gap:70px;align-items:center}.ey{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--a);font-weight:700}.hero h1{font-size:clamp(52px,8vw,96px);line-height:.94;letter-spacing:-.06em;margin:14px 0 25px}.lead{font-size:20px;color:var(--m);max-width:680px}.actions{display:flex;gap:12px;margin:30px 0}.btn{border:1px solid var(--l)}.portrait{aspect-ratio:4/5;border-radius:34px;overflow:hidden;background:#e9eef2}.portrait img{width:100%;height:100%;object-fit:cover}.stats{display:flex;gap:35px;margin-top:35px}.stats strong{display:block;font-size:28px}.stats span{color:var(--m);font-size:13px}.section{padding:105px 0;border-top:1px solid var(--l)}h2{font-size:clamp(36px,5vw,64px);line-height:1.02;letter-spacing:-.045em;margin:12px 0 40px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#fff;border:1px solid var(--l);border-radius:24px;padding:28px}.card h3{margin:10px 0}.muted{color:var(--m)}.dark{background:var(--t);color:#fff;border-radius:32px;padding:55px}.dark .muted{color:#b9c4c9}.footer{padding-top:35px;padding-bottom:35px;color:var(--m);font-size:13px}@media(max-width:800px){.links{display:none}.hero{grid-template-columns:1fr;gap:35px;padding-top:60px}.grid{grid-template-columns:1fr}.stats{flex-wrap:wrap}.hero h1{font-size:58px}.dark{padding:30px}}</style></head><body><header class="nav"><strong><?=e($doctor['short_name']??$doctor['name']??'Doctor')?></strong><nav class="links"><a href="/about/">Doktor haqida</a><a href="/expertise/">Mutaxassislik</a><a href="/research/">Ilmiy faoliyat</a><a href="/contact/">Aloqa</a></nav><a class="cta" href="/contact/">Qabulga yozilish</a></header><main><section class="hero wrap"><div><div class="ey"><?=e($doctor['title']??'Shifokor')?></div><h1><?=e($doctor['name']??'Doktor')?></h1><p class="lead"><?=e($doctor['bio']??'Professional tibbiy portfolio.')?></p><div class="actions"><a class="btn primary" href="/contact/">Qabulga yozilish</a><a class="btn" href="/about/">Profilni ko‘rish</a></div><div class="stats"><?php foreach(($doctor['stats']??[]) as $s):?><div><strong><?=e($s['value']??'')?></strong><span><?=e($s['label']??'')?></span></div><?php endforeach;?></div></div><div class="portrait"><img src="/uploads/profile/doctor.jpg" alt="<?=e($doctor['name']??'Doktor')?>" onerror="this.style.display='none'"></div></section><section class="section"><div class="wrap"><div class="ey">01 / ABOUT</div><h2><?=e($about['headline']??'Professional yondashuv.')?></h2><p class="lead"><?=e($about['bio']??'')?></p></div></section><section class="section"><div class="wrap"><div class="ey">02 / EXPERTISE</div><h2>Mutaxassislik yo‘nalishlari.</h2><div class="grid"><?php foreach(array_slice($expertise['items']??[],0,3) as $x):?><article class="card"><div class="ey"><?=e($x['category']??'')?></div><h3><?=e($x['title']??'')?></h3><p class="muted"><?=e($x['description']??'')?></p></article><?php endforeach;?></div></div></section><section class="section"><div class="wrap"><div class="ey">03 / RESEARCH</div><h2>Ilmiy faoliyat va yutuqlar.</h2><div class="grid"><?php foreach(array_slice($research['publications']??[],0,3) as $r):?><article class="card"><div class="ey"><?=e($r['year']??'')?></div><h3><?=e($r['title']??'')?></h3><p class="muted"><?=e($r['source']??'')?></p></article><?php endforeach;?></div></div></section><section class="section"><div class="wrap"><div class="dark"><div class="ey">04 / CONTACT</div><h2><?=e($contact['headline']??'Qabul uchun bog‘laning.')?></h2><p class="muted"><?=e($contact['address']??'')?></p><a class="btn" style="display:inline-block;background:#fff" href="/contact/">Aloqa va qabul</a></div></div></section></main><footer class="footer wrap">© <?=date('Y')?> <?=e($doctor['name']??'Doctor')?> · Professional portfolio</footer></body></html>